<?php /** @var array $services @var string $basePath @var string $assetBase */ $serviceImage=fn(array $s): string=>$s['image_url']?:$assetBase.'/assets/images/services/'.(in_array($s['slug'],['lawn-maintenance','landscape-installation','property-cleanup'],true)?$s['slug']:'landscape-installation').'.webp'; ?><section class="l-page-hero"><p class="l-eyebrow">Services</p><h1>Everything your property needs.</h1><p>Choose focused seasonal work or build a consistent maintenance relationship.</p></section><section class="l-section l-card-grid"><?php foreach ($services as $service): ?><article class="l-card" id="<?= e_attr($service['slug']) ?>"><img src="<?= e_attr($serviceImage($service)) ?>" alt=""><p class="l-eyebrow"><?= e(ucfirst($service['audience'])) ?></p><h2><?= e($service['name']) ?></h2><p><?= e($service['summary']) ?></p><a href="<?= e_attr($basePath) ?>/services/<?= e_attr($service['slug']) ?>">Service details →</a></article><?php endforeach; ?></section>
